function(container, apiUrl, tables) {
  const tbody = container.querySelector("#interruption-tbody");
  let timeInterval = null;
  let startTime = null;

  // 時間表示更新
  function updateElapsedTime() {
    if (startTime) {
      const now = new Date();
      const diff = Math.floor((now - startTime) / 1000 / 60);
      const hours = Math.floor(diff / 60);
      const minutes = diff % 60;
      container.querySelector("#time-display").textContent = 
        `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
    }
  }

  // 中断開始時刻変更時の処理
  container.querySelector("#start-time").addEventListener("change", function() {
    if (this.value) {
      startTime = new Date(this.value);
      if (timeInterval) clearInterval(timeInterval);
      timeInterval = setInterval(updateElapsedTime, 60000);
      updateElapsedTime();
    }
  });

  // 現在時刻を初期値として設定
  const now = new Date();
  now.setSeconds(0, 0);
  container.querySelector("#start-time").value = now.toISOString().slice(0, 16);
  startTime = now;
  timeInterval = setInterval(updateElapsedTime, 60000);
  updateElapsedTime();

  // 関連作業項目表示の更新
  async function updateWorkItemDisplay() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      const currentWork = workRecords?.find(r => r.進捗状況 === "作業中");
      const display = container.querySelector("#work-item-display");
      if (currentWork) {
        display.textContent = `${currentWork.プロジェクト名} - ${currentWork.作業種別}`;
        display.style.color = "var(--text)";
      } else {
        display.textContent = "進行中の作業項目がありません";
        display.style.color = "var(--text-muted)";
      }
    } catch (error) {
      console.error("作業項目の取得に失敗:", error);
    }
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id || ''}">
        <td>${r.中断開始日時 ? new Date(r.中断開始日時).toLocaleString() : ""}</td>
        <td>${r.中断理由区分 || ""}</td>
        <td>${r.中断時間 ? Math.floor(r.中断時間 / 60) + "h" + (r.中断時間 % 60) + "m" : ""}</td>
        <td>
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; 
            ${r.影響度 === '重大' ? 'background: rgba(220, 38, 38, 0.1); color: #dc2626;' : 
              r.影響度 === '中程度' ? 'background: rgba(245, 158, 11, 0.1); color: #f59e0b;' : 
              'background: rgba(34, 197, 94, 0.1); color: #22c55e;'}">
            ${r.影響度 || ""}
          </span>
        </td>
        <td>${r.対応状況 || ""}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id || ''}" style="font-size: 11px; padding: 4px 8px;">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id || ''}" style="font-size: 11px; padding: 4px 8px; margin-left: 4px;">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ表示
  renderRows(tables[2]?.records || []);
  updateWorkItemDisplay();

  // 一時保存ボタン
  container.querySelector("#btn-temp-save").addEventListener("click", async function() {
    const formData = collectFormData();
    if (!formData.中断開始日時) {
      alert("中断開始時刻を入力してください");
      return;
    }

    formData.対応状況 = "対応中";

    const saved = await window.aivicApi.save(2, formData);
    if (saved) {
      alert("一時保存しました");
      const rows = await window.aivicApi.list(2);
      if (rows) renderRows(rows);
    }
  });

  // 記録完了ボタン
  container.querySelector("#btn-complete").addEventListener("click", async function() {
    const formData = collectFormData();
    if (!formData.中断開始日時 || !formData.中断理由区分) {
      alert("必須項目を入力してください");
      return;
    }

    // 中断終了時刻を現在時刻に設定
    formData.中断終了日時 = new Date().toISOString();
    formData.対応状況 = "解決済み";

    // 中断時間を計算
    const start = new Date(formData.中断開始日時);
    const end = new Date(formData.中断終了日時);
    formData.中断時間 = Math.floor((end - start) / 1000 / 60);

    const saved = await window.aivicApi.save(2, formData);
    if (saved) {
      alert("中断記録を完了しました");
      window.showScreen("scr-1778907251446");
    }
  });

  // フォームデータ収集
  function collectFormData() {
    const urgency = container.querySelector('input[name="urgency"]:checked')?.value || "中";
    const impacts = Array.from(container.querySelectorAll('input[type="checkbox"]:checked'))
      .map(cb => cb.value).join(", ");

    return {
      中断開始日時: container.querySelector("#start-time").value,
      中断理由区分: container.querySelector("#reason-category").value,
      中断理由詳細: container.querySelector("#reason-detail").value,
      影響度: urgency === "高" ? "重大" : urgency === "中" ? "中程度" : "軽微",
      記録者ID: "current-user-id" // 実際の実装では現在のユーザーIDを使用
    };
  }

  // 写真添付ボタン
  container.querySelector("#btn-photo").addEventListener("click", function() {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = "image/*";
    input.onchange = function(e) {
      if (e.target.files.length > 0) {
        alert(`写真「${e.target.files[0].name}」を添付しました`);
      }
    };
    input.click();
  });

  // 音声メモボタン
  container.querySelector("#btn-voice").addEventListener("click", function() {
    alert("音声メモ機能は開発中です");
  });

  // 行レベル操作（編集・削除）
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    const editBtn = e.target.closest(".edit-btn");

    if (deleteBtn) {
      if (!confirm("この中断記録を削除しますか？")) return;
      await window.aivicApi.delete(2, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(2);
      if (rows) renderRows(rows);
    }

    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(2);
      const record = rows?.find(r => r.id === id);
      if (record) {
        // フォームに既存データを設定
        container.querySelector("#start-time").value = record.中断開始日時?.slice(0, 16) || "";
        container.querySelector("#reason-category").value = record.中断理由区分 || "";
        container.querySelector("#reason-detail").value = record.中断理由詳細 || "";

        // 緊急度設定
        const urgencyMap = {"重大": "高", "中程度": "中", "軽微": "低"};
        const urgencyValue = urgencyMap[record.影響度] || "中";
        const urgencyRadio = container.querySelector(`input[name="urgency"][value="${urgencyValue}"]`);
        if (urgencyRadio) urgencyRadio.checked = true;
      }
    }
  });

  // クリーンアップ
  return function cleanup() {
    if (timeInterval) {
      clearInterval(timeInterval);
    }
  };
}
